where maalepunkt_id = '707057500058145938';

-- 3) Står som «Registrert hos Entelios», men finnes IKKE i noen Entelios-liste:
--    Lilletunveien 6A -> tilbake til «Sendt Entelios» (må meldes inn)
update public.strombestillinger set status = 'Sendt Entelios'
where maalepunkt_id = '707057500058186320' and status = 'Bekreftet';
--    Elgsetergate 16 (...390) finnes ikke hos Entelios -> på vent til Sandra/Borg har avklart
update public.strombestillinger
set status = 'På vent',
    kommentar = concat_ws(' | ', 'På vent 22.10.2026: ikke på Entelios-listen 20.10, avklar med Borg', nullif(kommentar, ''))
where maalepunkt_id = '707057500069389390' and status = 'Bekreftet';

-- 4) Kontroll
select status, count(*) from public.strombestillinger group by status order by 1;
